	.long 0x00000125			; +0x88  (scalar or offset 0x125)     unresolved -- see the notes
					;        KN5000: 338, a SCALAR (DSP1 stream bias)
	.long 0x0004E3DC			; +0x8C  ToneDB_PercSourceNameList1   208 x 16-byte named wave-catalogue rows
